import numpy as np
import time


def _R(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return -1.0
    conv = np.convolve(h, h)
    L = np.concatenate(([0.0], conv, [0.0]))
    l2 = np.sum(L[:-1]**2 + L[:-1]*L[1:] + L[1:]**2) / 3.0
    l1 = s * s
    linf = L.max()
    if linf <= 0:
        return -1.0
    return l2 / (l1 * linf)


