    Lp[-1] = 0.0
    Lp[1:-1] = L
    a = Lp[:-1]
    b = Lp[1:]
    l2sq = np.sum(a * a + a * b + b * b) / 3.0
    l1 = s * s
    linf = Lp.max()
    if linf <= 0:
        return -1.0
    return l2sq / (l1 * linf)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = budget_seconds - 2.0

    def time_left():
        return deadline - (time.process_time() - t0)

    rng = np.random.default_rng(12345)

    if start is not None:
        best = np.asarray(start, dtype=float).copy()
        if best.size == 0 or best.sum() <= 0:
            best = np.ones(50)
    else:
        best = np.ones(50)
    best_R = _R(best)

    # Upsample to N=4000 by linear interpolation
    N = 4000
    if best.size != N:
        idx = np.linspace(0, best.size - 1, N)
        cur = np.interp(idx, np.arange(best.size), best)
    else:
        cur = best.copy()

    # Zero tiny values
    mx = cur.max()
    if mx > 0:
        cur[cur < 1e-6 * mx] = 0.0

    cur_R = _R(cur)
    if cur_R > best_R:
        best_R = cur_R
        best = cur.copy()

    n = cur.size
    mean_h = cur.mean() if cur.mean() > 0 else 1.0

    # Build candidate index set: first/last 20 nonzero, plus h > 0.8*max
    nz = np.nonzero(cur > 0)[0]
    idx_set = set()
    if nz.size > 0:
        for k in nz[:20]:
            idx_set.add(int(k))
        for k in nz[-20:]:
            idx_set.add(int(k))
    hi = np.nonzero(cur > 0.8 * mx)[0]
    for k in hi:
        idx_set.add(int(k))
    cand_idx = np.array(sorted(idx_set), dtype=int)
    if cand_idx.size == 0:
        cand_idx = np.arange(n)

    # Coordinate descent on candidate indices
    step_scales = [1e-2, 1e-3, 1e-4]
    for scale in step_scales:
        if time_left() <= 0:
            break
        step = scale * mean_h
        improved = True
        while improved and time_left() > 0:
            improved = False
            for i in cand_idx:
                if time_left() <= 0:
                    break
                old = cur[i]
                # try + and -
                for sign in (1.0, -1.0):
                    nv = old + sign * step
                    if nv < 0:
                        nv = 0.0
                    if nv == old:
                        continue
                    cur[i] = nv
                    r = _R(cur)
                    if r > cur_R:
                        cur_R = r
                        improved = True
                        if r > best_R:
                            best_R = r
                            best = cur.copy()
                        break
                    else:
                        cur[i] = old

    return best

import numpy as np
import time


def _R(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    conv = np.convolve(h, h)
    L = np.empty(conv.size + 2)
    L[0] = 0.0
    L[-1] = 0.0
    L[1:-1] = conv
    a = L[:-1]
    b = L[1:]
    l2sq = np.sum(a * a + a * b + b * b) / 3.0
    linf = L.max()
    if linf <= 0:
        return 0.0
    return l2sq / (s * s * linf)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    def left():
        return deadline - time.process_time()

    # ---- Build a strong analytic candidate family: the optimum is known to be
    # a smooth bump; paramterize f(t) = max(0, 1 - |t|^p)^q and also a
    # "flatter" family exp(-|t|^a). Scan cheaply at moderate N, then lift.
    if start is not None:
        sarr = np.asarray(start, dtype=float).copy()
        if sarr.ndim != 1 or sarr.size == 0 or sarr.sum() <= 0:
            sarr = None
    else:
        sarr = None

    best = None
    best_R = -1.0

    def consider(h):
        nonlocal best, best_R
        if h is None or h.size == 0 or h.size > 50000:
            return
        h = np.maximum(np.asarray(h, dtype=float), 0.0)
        if h.sum() <= 0:
            return
        r = _R(h)
        if r > best_R:
            best_R = r
            best = h.copy()

    if sarr is not None:
        consider(sarr)

    # analytic scan at N around 2000 (cheap, R nearly N-independent)
    Nscan = 2000
    t = np.linspace(-1, 1, Nscan)
    at = np.abs(t)
    for p in np.linspace(0.4, 3.0, 14):
        base = np.maximum(0.0, 1.0 - at ** p)
        for q in np.linspace(0.15, 2.5, 14):
            consider(base ** q)
    for a in np.linspace(0.5, 3.0, 14):
        consider(np.exp(-(at ** a)))

    # ---- Lift winner to full resolution, then smooth-basis hill climb ----
    def resample(h, n):
        if h.size == n:
            return h.copy()
        xi = np.linspace(0, 1, h.size)
        xo = np.linspace(0, 1, n)
        return np.maximum(np.interp(xo, xi, h), 0.0)

    N = 50000
    cur = resample(best, N)
    cur_R = _R(cur)
    print(f"init R={cur_R:.9f} N={cur.size}")

    # cosine basis for smooth multiplicative perturbations
    K = 40
    tt = np.linspace(0, 1, N)
    B = np.array([np.cos(np.pi * (k + 1) * tt) for k in range(K)])

    def norm(h):
        m = h.max()
        return h / m if m > 0 else h

    steps = 0.08 * (0.85 ** np.arange(K))
    rng = np.random.default_rng(99)

    while left() > 0:
        improved = False
        for k in rng.permutation(K):
            if left() <= 0:
                break
            bk = B[k]
            for sgn in (1.0, -1.0):
                amp = sgn * steps[k]
                cand = norm(cur * np.exp(amp * bk))
                r = _R(cand)
                if r > cur_R + 1e-13:
                    cur, cur_R = cand, r
                    steps[k] *= 1.25
                    improved = True
                    break
            else:
                steps[k] *= 0.7
        if cur_R > best_R:
            best, best_R = cur.copy(), cur_R
        if not improved:
            steps = np.maximum(steps, 1e-5)
            # tiny nudge to escape
            k = rng.integers(K)
            cand = norm(cur * np.exp(0.01 * rng.standard_normal() * B[k]))
            r = _R(cand)
            if r > cur_R:
                cur, cur_R = cand, r

    best = np.maximum(best, 0.0)
    if best.sum() <= 0:
        best = np.ones(50)
    if best.size > 50000:
        best = best[:50000]
    print(f"final R={_R(best):.9f} N={best.size}")
    return best
